    /// <summary>Plan furniture for the room containing (x, y). Pure.</summary>
    public static PlannerPlan planFurnish(SimState state, int x, int y)
    {
        var room = Rooms.roomAt(state, x, y);
        if (!Js.T(room))
        {
            return new() { commands = [], notes = ["Not an enclosed room: close it in with walls and a door first."] };
        }
        var designation = Rooms.designationOf(state, room);
        if (!Js.T(designation))
        {
            return new() { commands = [], notes = ["This room has no purpose yet: give it one with a Rooms tool first."] };
        }
        var status = Rooms.evaluateRoom(state, room, designation.purpose);
        List<string> notes = [];
        foreach (var r in Js.Iter(status.requirements))
        {
            if (Js.T(r.met))
            {
                continue;
            }
            if (r.label == "has a door")
            {
                notes.push("Needs a door: build one in its wall.");
            }
        }
        if (designation.purpose == "messhall")
        {
            return planMessHall(state, room, notes);
        }
        if (designation.purpose == "infirmary")
        {
            return planInfirmary(state, room, notes);
        }
        if (designation.purpose == "barracks")
        {
            return planBarracks(state, room, notes);
        }
        if (designation.purpose != "housing")
        {
            var name = new() { storage = "Storage", armory = "An armory", recroom = "A rec room", housing = "", messhall = "", infirmary = "", barracks = "", workshop = "A workshop (build a workbench in it)", graveyard = "A graveyard", greenhouse = "A greenhouse (farm plots in it grow all year)", cell = "Cells (raiders brought down may be taken alive and held here)" }[Js.Idx(designation.purpose)];
            notes.push($"{Js.Str(name)} needs no furniture yet.");
            return new() { commands = [], notes = notes };
        }
        return planHousing(state, room, notes);
    }

    /// <summary>Seats around one table in the open (its four sides).</summary>
    public const int SEATS_PER_TABLE = 4;

    /// <summary>Infirmary beds the planner wants: one per this many survivors.</summary>
    public const int INFIRMARY_PATIENTS_PER_BED = 4;

    /// <summary>Beds for the colony, up to the room's capacity, along walls and away from doors.</summary>
    public static PlannerPlan planHousing(SimState state, Room room, List<string> notes)
    {
        var capacity = JsMath.floor(((double)(room.tiles.length) / (Rooms.TILES_PER_BED)));
        bool inRoom(Point p)
        {
            return Rooms.labelAt(state, p.x, p.y) == room.index;
        }
        var bedsHere = FurnitureMod.ofKind(state, "bed").filter((f) => Js.T(inRoom(f))).length + state.blueprints.filter((b) => (b.target == "bed") && Js.T(inRoom(b))).length;
        var bedsElsewhere = bedsInOtherHousing(state, room);
        var wanted = JsMath.min(capacity, JsMath.max(1, state.survivors.length - bedsElsewhere));
        var toAdd = wanted - bedsHere;
        if (capacity == 0)
        {
            notes.push($"Too small for a bed (needs {Js.Str(Rooms.TILES_PER_BED)} tiles).");
            return new() { commands = [], notes = notes };
        }
        if (toAdd <= 0)
        {
            notes.push($"Already has {Js.Str(bedsHere)} bed{Js.Str((bedsHere == 1) ? "" : "s")}: enough for the colony.");
            return new() { commands = [], notes = notes };
        }
        var spots = bedSpots(state, room).slice(0, toAdd);
        List<Command> commands = spots.map((p) => new() { type = "designateBuild", x = Js.I(p.x), y = Js.I(p.y), structure = "bed" });
        notes.push($"Planned {Js.Str(spots.length)} bed{Js.Str((spots.length == 1) ? "" : "s")} (room holds {Js.Str(capacity)}, colony of {Js.Str(state.survivors.length)}).");
        if (spots.length < toAdd)
        {
            notes.push($"Only found room for {Js.Str(spots.length)}: clear some space.");
        }
        return new() { commands = commands, notes = notes };
    }

    public static double bedsInOtherHousing(SimState state, Room room)
    {
        var housing = Js.Set(state.roomDesignations.filter((d) => d.purpose == "housing").map((d) => Rooms.labelAt(state, d.x, d.y)).filter((label) => (label >= 0) && (label != room.index)));
        return FurnitureMod.ofKind(state, "bed").filter((f) => housing.has(Rooms.labelAt(state, f.x, f.y))).length;
    }

    /// <summary>Tables, one per SEATS_PER_TABLE survivors, out in the open so every side is a seat.</summary>
    public static PlannerPlan planMessHall(SimState state, Room room, List<string> notes)
    {
        bool inRoom(Point p)
        {
            return Rooms.labelAt(state, p.x, p.y) == room.index;
        }
        var tablesHere = FurnitureMod.ofKind(state, "table").filter((f) => Js.T(inRoom(f))).length + state.blueprints.filter((b) => (b.target == "table") && Js.T(inRoom(b))).length;
        var toAdd = JsMath.max(1, JsMath.ceil(((double)(state.survivors.length) / (SEATS_PER_TABLE)))) - tablesHere;
        if (toAdd <= 0)
        {
            notes.push($"Already has {Js.Str(tablesHere)} table{Js.Str((tablesHere == 1) ? "" : "s")}: enough seats for the colony.");
            return new() { commands = [], notes = notes };
        }
        List<Point> spots = [];
        foreach (var p in Js.Iter([.. freeSpots(state, room)].sort((a, b) => a.walls - b.walls).map((c) => c.p)))
        {
            if (spots.length == toAdd)
            {
                break;
            }
            if (spots.some((q) => (JsMath.abs(q.x - p.x) + JsMath.abs(q.y - p.y)) <= 2))
            {
                continue;
            }
            spots.push(p);
        }
        List<Command> commands = spots.map((p) => new() { type = "designateBuild", x = Js.I(p.x), y = Js.I(p.y), structure = "table" });
        notes.push($"Planned {Js.Str(spots.length)} table{Js.Str((spots.length == 1) ? "" : "s")} (seats for {Js.Str(SEATS_PER_TABLE)} each, colony of {Js.Str(state.survivors.length)}).");
        if (spots.length < toAdd)
        {
            notes.push($"Only found room for {Js.Str(spots.length)}: clear some space.");
        }
        return new() { commands = commands, notes = notes };
    }

