    public static List<Point> bedSpots(SimState state, Room room)
    {
        return freeSpots(state, room).sort((a, b) => b.walls - a.walls).map((c) => c.p);
    }

    /// <summary>Free floor in the room, not next to a door, with how many walls touch it. In scan order.</summary>
    public static List<FreeSpotsResult> freeSpots(SimState state, Room room)
    {
        var __d0 = state;
        var grid = __d0.grid;
        var taken = new JsSet<string>([.. state.items.filter((i) => Js.T(i.pos)).map((i) => $"{Js.Str(i.pos!.x)},{Js.Str(i.pos!.y)}"), .. state.furniture.map((f) => $"{Js.Str(f.x)},{Js.Str(f.y)}"), .. state.blueprints.map((b) => $"{Js.Str(b.x)},{Js.Str(b.y)}"), .. state.farm.map((p) => $"{Js.Str(p.x)},{Js.Str(p.y)}")]);
        List<FreeSpotsCandidates> candidates = [];
        foreach (var i in Js.Iter(room.tiles))
        {
            var p = new() { x = Js.I(i % grid.width), y = Js.I(JsMath.floor(((double)(i) / (grid.width)))) };
            if (taken.has($"{Js.Str(p.x)},{Js.Str(p.y)}"))
            {
                continue;
            }
            var around = Grids.neighbours4(grid, p.x, p.y).map((n) => Grids.getTile(grid, n.x, n.y));
            var edges = Grids.neighbours4(grid, p.x, p.y).map((n) => grid.edges[Js.Idx(Grids.edgeBetween(grid, p.x, p.y, n.x, n.y))] ?? Grids.EDGE_NONE);
            if (around.includes("door") || edges.includes(Grids.EDGE_DOOR))
            {
                continue;
            }
            candidates.push(new() { p = p, walls = around.filter((t) => t == "wall").length + edges.filter((e) => e == Grids.EDGE_WALL).length });
        }
        return candidates;
    }
